// Generated by energy_v2/extract_candidates.py from the public Dartmouth source crawl.
// Every record is an unreviewed keyword/name match, not a verified fact.

export type EnergyTechnology =
  | "steam_to_hot_water" | "solar" | "geoexchange" | "heat_pump" | "chilled_water" | "biomass"
  | "hvac" | "lighting" | "insulation" | "heat_recovery" | "electrical" | "fuel_oil" | "emissions";

export type EnergyEvidence = {
  osmId: string;
  twinObjects: string[];
  candidateCount: number;
  sourceCount: number;
  technologies: { id: EnergyTechnology; count: number }[];
  projects: { id: string; name: string }[];
  yearRange: [number, number] | null;
  statusHints: Partial<Record<"completed" | "in_progress" | "planned", number>>;
  evidence: {
    text: string;
    url: string;
    published: string | null;
    confidence: "high" | "medium" | "none";
    technologies: EnergyTechnology[];
  }[];
  generatedAt: string;
};

